// Orbit workspace · synthetic showcase project
import { AgentPanel } from "./components/AgentPanel";

export const workspace = {
  name: "Orbit workspace",
  mode: "local-first",
  agentStatus: "awaiting approval",
};

export function renderWorkspace(root: HTMLElement) {
  root.innerHTML = `
    <main class="workspace">
      <h1>${workspace.name}</h1>
      <p>Review every change. Keep control.</p>
    </main>
  `;
  AgentPanel(root, workspace.agentStatus);
}

