// Synthetic component · no agent is executed
export function AgentPanel(root: HTMLElement, agentStatus: string) {
  const panel = document.createElement("section");
  panel.className = "agent-panel";
  panel.textContent = `Agent: ${agentStatus}`;
  root.append(panel);
}

